  List<Map<String, dynamic>?> run(List<SyncParallelJob> jobs) {
    if (!ready) {
      throw StateError('SyncWorkerPool "$name" is not booted');
    }
    if (jobs.isEmpty) return const <Map<String, dynamic>>[];
    final replies = _submit(jobs);
    return _collect(replies);
