              _detectSourceCommit(agentRoot),
          Directory(_optionValue(rest, '--out') ?? 'dist'),
          extraDirs: _optionValues(rest, '--include'));
      _printResult(agentName, version, result);
      return 0;
    } on AgentPackException catch (e) {
      _writer('Error: ${e.message}');
      return 1;
    }
  }

