Map<String, dynamic>? _resolveContentJob(Map<String, dynamic> args) {
  final config = (
    rootUrl: args['rootUrl'] as String,
    baseUrl: args['baseUrl'] as String,
    headers: _argsHeaders(args),
    apiVersion: '${args['apiVersion']}',
