      final result = AgentPackCompiler(agentRoot).compile(
          File(rest.first),
          version,
          _optionValue(rest, '--source-commit') ??
              _detectSourceCommit(agentRoot),
          Directory(_optionValue(rest, '--out') ?? 'dist'),
          extraDirs: _optionValues(rest, '--include'));
