  List<Mailbox> _submit(List<SyncParallelJob> jobs) {
    final replies = <Mailbox>[];
    for (final job in jobs) {
      final reply = Mailbox();
      replies.add(reply);
      _inboxes[_next].send(<String, dynamic>{
        'i': job.index,
        'kind': job.kind,
        'args': job.args,
        'reply': reply.asSendable,
      });
