Future<void> serveSyncWorker(
    SyncWorkerBoot boot, SyncWorkerRunner runner) async {
  await SyncHttpBridge.shared.boot();
  final inbox = ReceivePort();
  boot.handshake.send(inbox.sendPort);
  await for (final message in inbox) {
